import re; from .rules import RULES; P = {"TRUNCATE": r"^\s*TRUNCATE\b", "DELETE_NO_WHERE": r"\bDELETE\s+FROM\b(?!.*\bWHERE\b)", "UPDATE_NO_WHERE": r'(?:^\s*|\bAS\s*\(\s*)UPDATE\s+(?:ONLY\s+)?[\w".]+(?:\s+(?:AS\s+)?\w+)?\s+SET\b(?!.*\bWHERE\b)', "ADD_NOT_NULL_NO_DEFAULT": r'\bADD\s+(?!CONSTRAINT\b|CHECK\b|PRIMARY\b|UNIQUE\b|FOREIGN\b|EXCLUDE\b)(?:COLUMN\s+)?(?:IF\s+NOT\s+EXISTS\s+)?[\w".]+\s+(?![^,]*\bDEFAULT\b)[^,]*?\bNOT\s+NULL\b', "ALTER_TYPE": r'\bALTER\s+(?:COLUMN\s+)?[\w".]+\s+(?:SET\s+DATA\s+)?TYPE\b', "CREATE_INDEX_BLOCKING": r"^\s*CREATE\s+(?:UNIQUE\s+)?INDEX(?!\s+CONCURRENTLY\b)\b"}; TOK = re.compile(r"--[^\n]*|/\*.*?\*/|'(?:[^']|'')*'|\$(\w*)\$.*?\$\1\$|\x22(?:[^\x22]|\x22\x22)*\x22", re.S); clean = lambda sql: TOK.sub(lambda m: '"' + re.sub(r"[^\n]", "_", m.group(0)[1:-1]) + '"' if m.group(0)[0] == '"' else re.sub(r"[^\n]", " ", m.group(0)), sql); scan = lambda sql: [(sql[:m.start(1)].count("\n") + 1, r[0], r[1], r[3]) for m in re.finditer(r"\s*([^;]+)", clean(sql)) if m.group(1).strip() for r in RULES if re.search(P.get(r[0], r[2]), m.group(1), re.I | re.S)]
